use elements::hashes::Hash;
use simplicity::jet;
use simplicity::RedeemNode;
use simplicity_sys::tests::{run_program, TestUpTo};

use txgen::{
    seed_data_delete,
    seed_data_new,
    seed_data_prog_data,
    seed_data_prog_len,
    seed_data_read_program,
};

fn dummy_tx() -> elements::Transaction {
    use elements::hex::FromHex;
    let bytes: Vec<u8> = FromHex::from_hex("").unwrap();
    elements::encode::deserialize(&bytes).unwrap()
}

fn do_test(mut data: &[u8]) {
    unsafe {
        let seed_data = seed_data_new();

        for _ in 0..100 {
            let nbytes = seed_data_read_program(&mut *seed_data, data.as_ptr(), data.len());
            if nbytes == 0 {
                break;
            }
            data = &data[nbytes..];

            /*
            let cmr = unsafe { core::slice::from_raw_parts(seed_data_cmr(&*seed_data), 32) };
            let amr = unsafe { core::slice::from_raw_parts(seed_data_amr(&*seed_data), 32) };
            */
            let prog = core::slice::from_raw_parts(
                seed_data_prog_data(&*seed_data),
                seed_data_prog_len(&*seed_data),
            );

            let prog_iter = simplicity::BitIter::new(prog.iter().copied());
            let wit_iter = simplicity::BitIter::new(data.iter().copied());
            match RedeemNode::<jet::Elements>::decode(prog_iter, wit_iter) {
                Ok(_prog) => {
                    let tx = dummy_tx();
                    let taproot = elements::taproot::TaprootBuilder::new()
                        .add_leaf(0, elements::Script::new())
                        .unwrap()
                        .finalize(
                            &elements::secp256k1_zkp::Secp256k1::new(),
                            elements::schnorr::UntweakedPublicKey::from_slice(&[0x18; 32]).unwrap(),
                        )
                        .unwrap()
                        .control_block(&(elements::Script::new(), Default::default()))
                        .unwrap();
                    let mut mach = simplicity::BitMachine::for_program(&_prog);
                    let env = simplicity::jet::elements::ElementsEnv::new(
                        std::sync::Arc::new(tx),
                        vec![],
                        0,
                        _prog.cmr(),
                        taproot,
                        None,
                        elements::BlockHash::from_byte_array([0xbc; 32]),
                    );
                    let _ = mach.exec(&_prog, &env); //.unwrap();

                    // Cannot actually run without an environment
                    match run_program(prog, data, TestUpTo::CheckOneOne) {
                        Ok(..) => {},
                        Err(simplicity::ffi::tests::ffi::SimplicityErr::FailCode) => {},
                        Err(e) => panic!("run_program error {e}"),
                    }
                }
                Err(simplicity::Error::Decode(simplicity::decode::Error::EndOfStream)) |
                Err(simplicity::Error::Decode(simplicity::decode::Error::BitIter(..))) => {
                    // witness data might be bad
                }
                Err(_e) => {
                    panic!("bad decode: {_e}");
                }
            }
        }
        seed_data_delete(seed_data);
    }
    /*
    use simplicity::dag::{DagLike as _, MaxSharing};
    for node in prog.post_order_iter::<MaxSharing<simplicity::node::Redeem<simplicity::jet::Elements>>>() {
        println!("{}: {}", node.node.inner(), node.node.arrow());
    }
    */
}

fn main() {
    loop {
        honggfuzz::fuzz!(|data| {
            do_test(data);
        });
    }
}

#[cfg(test)]
mod tests {
    fn extend_vec_from_hex(hex: &str, out: &mut Vec<u8>) {
        let mut b = 0;
        for (idx, c) in hex.as_bytes().iter().enumerate() {
            b <<= 4;
            match *c {
                b'A'..=b'F' => b |= c - b'A' + 10,
                b'a'..=b'f' => b |= c - b'a' + 10,
                b'0'..=b'9' => b |= c - b'0',
                _ => panic!("Bad hex"),
            }
            if (idx & 1) == 1 {
                out.push(b);
                b = 0;
            }
        }
    }

    #[test]
    fn duplicate_crash() {
        let mut a = Vec::new();
        extend_vec_from_hex("", &mut a);
        super::do_test(&a);
    }
}
